mapper.delete:
delete from corgi_activity_attender
where user_id = #{userSignUp.userId}
and activity_id = #{userSignUp.activityId}

mapper.update:
update corgi_activity_attender
set `status` = #{userSignUp.status}
where user_id = #{userSignUp.userId} and activity_id = #{userSignUp.activityId}

mapper.select:
select `status`
from corgi_activity_attender
where user_id = #{userId} and activity_id = #{activityId}

select
count(1)
from corgi_activity_attender a
where a.activity_id = #{activityId}

    and a.`status` = #{status}

select activity_id from corgi_activity_attender
where user_id = #{userId} order by update_time desc
limit #{start},#{size}
